import{_ as p,a0 as l,w as d,s,ao as i,I as a,x as t,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"如何交互式地创建一个Docker容器 | LCTT x X-CMD","titleTemplate":false,"description":"如何交互式地创建一个Docker容器 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何交互式地创建一个Docker容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何交互式地创建一个Docker容器 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 How to Interactively Create a Docker Container","title":"如何交互式地创建一个Docker容器","tag":"201505","desc":""},"relativePath":"201505/20150324 How to Interactively Create a Docker Container.md","filePath":"[post].md"}'),c={name:"201505/20150324 How to Interactively Create a Docker Container.md"};function m(g,e,h,u,k,f){const o=l("Link");return d(),s("div",null,[e[16]||(e[16]=i('<h1 id="如何交互式地创建一个docker容器" tabindex="-1">如何交互式地创建一个Docker容器 <a class="header-anchor" href="#如何交互式地创建一个docker容器" aria-label="Permalink to “如何交互式地创建一个Docker容器”">​</a></h1><p>大家好，今天我们来学习如何使用一个docker镜像交互式地创建一个Docker容器。当我们从镜像中启动一个Docker进程，Docker就会获取该镜像及其父镜像，并重复这个过程，直到到达基础镜像。然后联合文件系统（UFS）会在其顶层添加一个读写层。读写层被称之为容器，它包含了一些关于父镜像信息及一些其他的信息，如唯一ID，网络配置和资源限制等。容器是有状态的，其状态可以从 <strong>运行态</strong> 切换到 <strong>退出态</strong>。一个处于 <strong>运行态</strong>的容器包含了在CPU上面运行的进程树，于其它在该主机上运行的进程相隔离，而<strong>退出态</strong>是指文件系统的状态，并保留了其退出值。你可以使用它来启动，停止和重启一个容器。</p><p>Docker技术为IT界带来了巨大的改变，它使得云服务可以用来共享应用和工作流程自动化，使得应用可以用组件快速组合，消除了开发、品质保证、产品环境间的摩擦。在这篇文章中，我们将会建立CentOS环境，然后用Apache网络服务器提供一个网站服务。</p><p>这是一个快速且容易的教程，讨论我们怎样使用交互的shell，以交互的方式来创建一个容器。</p><h3 id="_1-运行一个docker实例" tabindex="-1">1. 运行一个Docker实例 <a class="header-anchor" href="#_1-运行一个docker实例" aria-label="Permalink to “1. 运行一个Docker实例”">​</a></h3>',5)),a("p",null,[e[1]||(e[1]=t("Docker首先会尝试从本地取得并运行所需的镜像，如果在本地主机上没有发现，它就会从",-1)),r(o,{href:"https://registry.hub.docker.com/"},{default:n(()=>[...e[0]||(e[0]=[t("Docker公共注册中心",-1)])]),_:1}),e[2]||(e[2]=t("拉取。这里，我们将会拉取镜像并在 Docker 容器中创建一个fedora实例，并连接到它的 tty 上的bash shell。",-1))]),e[17]||(e[17]=i(`<pre><code># docker run -i -t fedora bash
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/downloading-fedora-base-image.png" alt="Downloading Fedora Base Image"></p><h3 id="_2-安装apache网络服务器" tabindex="-1">2.安装Apache网络服务器 <a class="header-anchor" href="#_2-安装apache网络服务器" aria-label="Permalink to “2.安装Apache网络服务器”">​</a></h3><p>现在，在我们的Fedora基本镜像实例准备好后，我们将会开始交互式地安装Apache网络服务器，而不是为它创建Dockerfile。为了做到这点，我们需要在终端或者shell运行以下命令。</p><pre><code># yum update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-httpd2.png" alt="Installing httpd"></p><pre><code># yum install httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-httpd2.png" alt="Installing httpd"></p><pre><code># exit
</code></pre><h3 id="_3-保存镜像" tabindex="-1">3.保存镜像 <a class="header-anchor" href="#_3-保存镜像" aria-label="Permalink to “3.保存镜像”">​</a></h3><p>现在，我们要去保存在Fedora实例里做的修改。要做到这个，我们首先需要知道实例的容器ID。而为了得到ID，我们又需要运行以下命令（LCTT 译注：在容器外执行该命令）。</p><pre><code># docker ps -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/docker-running-container.png" alt="Docker Running Container"></p><p>然后，我们会保存这些改变为一个新的镜像，请运行以下命令。</p><pre><code># docker commit c16378f943fe fedora-httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/committing-fedora-httpd.png" alt="committing fedora httpd"></p><p>这里，修改已经通过使用容器ID保存起来了，镜像名字叫fedora-httpd。为了确认新的镜像是否在运行，我们将运行以下命令。</p><pre><code># docker images
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/view-docker-images.png" alt="view docker images"></p><h3 id="_4-添加内容到新的镜像" tabindex="-1">4. 添加内容到新的镜像 <a class="header-anchor" href="#_4-添加内容到新的镜像" aria-label="Permalink to “4. 添加内容到新的镜像”">​</a></h3><p>我们自己新的Fedora Apache镜像正成功的运行，现在我们想添加一些我们网站的网页内容到Apache网络服务器，使得网站能够开箱即用。为做到这点，我们需要创建一个新的Dockerfile，它会处理从复制网页内容到启用80端口的所有操作。要达到这样的目的，我们需要使用我们最喜欢的文本编辑器创建Dockerfile文件，像下面演示的一样。</p><pre><code># nano Dockerfile
</code></pre><p>现在，我们需要添加以下的命令行到文件中。</p><pre><code>FROM fedora-httpd
ADD mysite.tar /tmp/
RUN mv /tmp/mysite/* /var/www/html
EXPOSE 80
ENTRYPOINT [ &quot;/usr/sbin/httpd&quot; ]
CMD [ &quot;-D&quot;, &quot;FOREGROUND&quot; ]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/configuring-Dockerfile.png" alt="configuring Dockerfile"></p><p>这里，上述的Dockerfile中，放在mysite.tar里的网页内容会自动解压到/tmp/文件夹里。然后，整个站点会被移动到Apache的网页根目录/var/www/html/，命令expose 80会打开80端口，这样网站就能正常访问了。其次，入口点放在了/usr/sbin/https里面，保证Apache服务器能够执行。</p><h3 id="_5-构建并运行一个容器" tabindex="-1">5. 构建并运行一个容器　### <a class="header-anchor" href="#_5-构建并运行一个容器" aria-label="Permalink to “5. 构建并运行一个容器　###”">​</a></h3><p>现在，我们要用刚刚创建的Dockerfile创建我们的容器，以便将我们的网站添加到上面。为做到这，我们需要运行以下命令。</p><pre><code># docker build -rm -t mysite .
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/building-mysite-image.png" alt="Building mysite Image"></p><p>建立好我们的新容器后，我们需要要用下面的命令来运行容器。</p><pre><code># docker run -d -P mysite
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/running-mysite-container.png" alt="Running mysite Container"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>最后，我们已经成功的以交互式的方式建立了一个Docker容器。在本节方法中，我们是直接通过交互的shell命令建立我们的容器和镜像。在建立与配置镜像与容器时，这种方法十分简单且快速。如果你有任何问题，建议和反馈，请在下方的评论框里写下来，以便我们可以提升或者更新我们的文章。谢谢！祝生活快乐 😃</p><hr>`,36)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),r(o,{href:"http://linoxide.com/linux-how-to/interactively-create-docker-container/"},{default:n(()=>[...e[3]||(e[3]=[t("http://linoxide.com/linux-how-to/interactively-create-docker-container/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=t("作者：",-1)),r(o,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[5]||(e[5]=[t("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),r(o,{href:"https://github.com/wi-cuckoo"},{default:n(()=>[...e[6]||(e[6]=[t("wi-cuckoo",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const T=p(c,[["render",m]]);export{b as __pageData,T as default};
